// Review round 1 (PR #6) finding F3: every `ModelSpec.runtimeWasm` path must be
// actually produced by the repo — either tracked in git or generated by a
// vendoring script — or the offline story for that tier is a 404.
//
// The frozen CC-03.1 registry suite pins row fields but not the existence of
// the same-origin wasm assets; this additive check closes that hole. It is
// static (no network, no build): it only asserts that the path's producer is
// present in the tree, so it can never pass on a phantom path.
import { describe, expect, test } from 'vitest'
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { MODEL_REGISTRY } from '@engine/model/registry'
import { REPO_ROOT } from '../../../helpers/repo'

/**
 * name → the script that writes it into `public/`. A path with no tracked file
 * and no listed generator is a phantom: `ensureOffline` would fetch a 404.
 */
const GENERATORS: Record<string, { script: string; marker: string }> = {
  'wasm/': { script: 'scripts/copy-wasm.ts', marker: 'copyRuntimeWasm' },
  'sherpa/': { script: 'scripts/copy-vendor-assets.ts', marker: "join(repoRoot, 'public', 'sherpa')" },
}

function producerFor(urlPath: string): { kind: 'tracked' } | { kind: 'generated'; script: string } | null {
  const relative = urlPath.replace(/^\//, '')
  if (existsSync(join(REPO_ROOT, 'public', relative))) {
    // Anything already materialised is fine regardless of how it got there.
    return { kind: 'tracked' }
  }
  for (const [prefix, generator] of Object.entries(GENERATORS)) {
    if (relative.startsWith(prefix)) {
      const source = join(REPO_ROOT, generator.script)
      if (existsSync(source) && readFileSync(source, 'utf8').includes(generator.marker)) {
        return { kind: 'generated', script: generator.script }
      }
    }
  }
  // The needle runtime lives under /wasm but comes from the cactus package's
  // vendor manifest rather than the ORT dist dir — same script, different export.
  if (relative.startsWith('wasm/needle.')) {
    const source = join(REPO_ROOT, 'scripts/copy-vendor-assets.ts')
    if (existsSync(source) && readFileSync(source, 'utf8').includes('copyNeedleRuntime')) {
      return { kind: 'generated', script: 'scripts/copy-vendor-assets.ts' }
    }
  }
  return null
}

describe('F3: every runtimeWasm path has a real producer in the repo', () => {
  const rows = Object.values(MODEL_REGISTRY) as { id: string; runtimeWasm: string[] }[]

  test('at least one row declares runtime wasm (the check is not vacuous)', () => {
    expect(rows.filter((row) => row.runtimeWasm.length > 0).length).toBeGreaterThan(0)
  })

  test.each(rows.flatMap((row) => row.runtimeWasm.map((path) => ({ id: row.id, path }))))(
    'F3: $id runtime $path is tracked or script-generated',
    ({ path }) => {
      expect(path.startsWith('/'), `${path} must be a same-origin absolute path`).toBe(true)
      const producer = producerFor(path)
      expect(producer, `${path} is not tracked in public/ and has no generator script — ensureOffline would 404`).not.toBeNull()
    },
  )

  test('F3: the cactus-needle runtime is SHA-256-verified against its vendor manifest', () => {
    const source = readFileSync(join(REPO_ROOT, 'scripts', 'copy-vendor-assets.ts'), 'utf8')
    expect(source).toContain('copyNeedleRuntime')
    expect(source).toContain("createHash('sha256')")
    expect(source).toContain('manifest.json')
  })
})